function segments(value: string): string[] {
  if (!value.startsWith("/") || value.includes("?") || value.includes("#")) {
    throw new TypeError("Invalid path syntax");
  }
  if (value === "/") return [];
  const result = value.slice(1).split("/");
  if (result.some((part) => part.length === 0)) {
    throw new TypeError("Empty path segment");
  }
  return result;
}

export function matchPath(
  routes: readonly RouteSpec[],
  path: string,
): RouteMatch | null {
  const pathParts = segments(path);
  let fallback: RouteSpec | undefined;
  const candidates: Array<{ route: RouteSpec; params: Record<string, string>; score: number; index: number }> = [];

  routes.forEach((route, index) => {
    if (route.pattern === "*") {
      fallback ??= route;
      return;
    }
    const patternParts = segments(route.pattern);
    const names = patternParts
      .filter((part) => part.startsWith(":"))
      .map((part) => part.slice(1));
    if (names.some((name) => name.length === 0) || new Set(names).size !== names.length) {
      throw new TypeError("Invalid route parameter");
    }
    if (patternParts.length !== pathParts.length) return;

    const params: Record<string, string> = {};
    let score = 0;
    for (let i = 0; i < patternParts.length; i += 1) {
      const patternPart = patternParts[i]!;
      const pathPart = pathParts[i]!;
      if (patternPart.startsWith(":")) params[patternPart.slice(1)] = pathPart;
      else if (patternPart === pathPart) score += 1;
      else return;
    }
    candidates.push({ route, params, score, index });
  });

  candidates.sort((a, b) => a.score - b.score || a.index - b.index);
  const best = candidates[0];
  if (best) return { destination: best.route.destination, params: { ...best.params } };
  return fallback ? { destination: fallback.destination, params: {} } : null;
}

