import { matchPath, RouteSpec } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function throwsTypeError(fn: () => void, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

deepEqual(matchPath([], '/'), null, 'empty routes return null');
deepEqual(matchPath([{ pattern: '/', destination: 'root' }], '/'), { destination: 'root', params: {} }, 'root matches root');
deepEqual(matchPath([{ pattern: '/', destination: 'root' }], '/x'), null, 'root does not match another path');

const routes: readonly RouteSpec[] = Object.freeze([
  Object.freeze({ pattern: '*', destination: 'fallback-one' }),
  Object.freeze({ pattern: '/:section/fixed', destination: 'parameter-first' }),
  Object.freeze({ pattern: '/shop/:item', destination: 'literal-first' }),
  Object.freeze({ pattern: '/shop/fixed', destination: 'most-specific' }),
  Object.freeze({ pattern: '*', destination: 'fallback-two' })
]);
const before = JSON.stringify(routes);
deepEqual(matchPath(routes, '/shop/fixed'), { destination: 'most-specific', params: {} }, 'selects greatest literal specificity');
deepEqual(matchPath(routes, '/other/fixed'), { destination: 'parameter-first', params: { section: 'other' } }, 'captures raw parameter');
deepEqual(matchPath(routes, '/shop/value%20raw'), { destination: 'literal-first', params: { item: 'value%20raw' } }, 'does not decode parameters');
deepEqual(matchPath(routes, '/nothing'), { destination: 'fallback-one', params: {} }, 'uses first fallback last');
deepEqual(JSON.stringify(routes), before, 'does not mutate or reorder routes');

const tied: readonly RouteSpec[] = [
  { pattern: '/:first/x', destination: 'first' },
  { pattern: '/a/:second', destination: 'second' }
];
deepEqual(matchPath(tied, '/a/x'), { destination: 'first', params: { first: 'a' } }, 'uses declaration order on specificity tie');

const freshOne = matchPath([{ pattern: '/:id', destination: 'd' }], '/x');
const freshTwo = matchPath([{ pattern: '/:id', destination: 'd' }], '/x');
assert(freshOne !== null && freshTwo !== null && freshOne.params !== freshTwo.params, 'returns fresh parameter objects');

for (const path of ['relative', '*', '/a//b', '/a?x', '/a#x']) {
  throwsTypeError(() => matchPath([], path), `rejects malformed path ${path}`);
}
for (const pattern of ['relative', '/a//b', '/x/:', '/:id/:id', '/a?x', '/a#x']) {
  throwsTypeError(() => matchPath([{ pattern, destination: 'bad' }], '/a/b'), `rejects malformed pattern ${pattern}`);
}

